"""Build printable HTML academic documentation from retained measured evidence."""
import html
import json
from pathlib import Path
import xml.etree.ElementTree as ET

CSS='''body{font:16px/1.65 system-ui,Segoe UI,sans-serif;color:#182330;max-width:1000px;margin:50px auto;padding:0 30px}h1{font-size:32px;line-height:1.25;color:#000}h2{font-size:22px;margin-top:34px;color:#000}p{margin:14px 0}table{border-collapse:collapse;width:100%;margin:22px 0;font-size:14px}th,td{border:1px solid #d9d9d9;padding:11px 14px;text-align:left;vertical-align:middle}th{background:#193b59;color:white}tr:nth-child(even){background:#f2f5f8}a{color:#155a91}img{max-width:100%;height:auto}small{color:#4c5865}.meta{color:#52606e;margin-bottom:30px}@media print{body{font-size:11pt;max-width:none;margin:0;padding:0}h1{font-size:22pt}h2{font-size:15pt;break-after:avoid}table{font-size:9pt}tr{break-inside:avoid}a{color:inherit}@page{margin:20mm}}'''

def page(title,body):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+CSS+'</style></head><body><h1>'+html.escape(title)+'</h1>'+body+'</body></html>'

def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

def build():
    root=Path('docs');root.mkdir(exist_ok=True)
    demo=json.loads(Path('results/demo_v3/demo_results.json').read_text())
    process=json.loads(Path('results/two_process_v3/results.json').read_text())
    benchmark=json.loads(Path('results/benchmark_v3/summary.json').read_text())
    tests=ET.parse('results/security_tests.xml').getroot()
    count=len(tests.findall('.//testcase'))
    failures=len(tests.findall('.//failure'))+len(tests.findall('.//error'))
    skipped=len(tests.findall('.//skipped'))
    synopsis='''<p class="meta">ISL project synopsis<br>Aditya Khanna · Registration number 240911662 · V IT · Section B<br>Manipal Institute of Technology · Manipal Academy of Higher Education<br>Guides Dr Snehal Samanth and Dr Anup Bhat</p>
<p>SecureLink implements and evaluates authenticated multimedia communication between a client terminal and a bank-server simulation. It supports text, images, audio and video, integrates traffic analysis and PCAP conversion, and demonstrates five security goals through implemented controls and reproducible experiments.</p>
<h2>Objective</h2><p>Design and evaluate a secure multimedia framework between two physical or simulated endpoints using mutual authentication, authenticated encryption, replay rejection, accountable audit records and bounded recovery after communication failures. Measure communication efficiency and validate security behaviour using attack tests and captured traffic.</p>
<h2>Problem statement</h2><p>An unsecured channel exposes transaction content and media to interception, alteration and impersonation. Replaying a valid request can duplicate an action, interrupted connections create uncertainty about completion, and an editable local log provides weak evidence of what happened. A compact academic framework should address these problems together and distinguish tested behaviour from unsupported security claims.</p>
<h2>Scope and implementation</h2><p>The Python implementation transfers UTF-8 text, PNG/JPEG images, WAV/MP3 audio and MP4 video. Authenticated 64 KiB chunks support upload and download with a 32 MiB file limit. Receiver-side persistence records each accepted offset, permitting reconnection and resume. A final SHA-256 verifies the complete file before successful completion. Safe basenames and media format metadata preserve usable received files.</p><p>The banking scenario uses synthetic identity media and a simulated transaction ledger. A device-scoped request ID makes repeated submissions idempotent: the same transaction cannot be committed twice under the same ID. No real accounts, balances, identity verification, regulatory compliance or financial transfers are claimed.</p>
<h2>Approved ISL modules</h2><p>Traffic Analysis uses Wireshark/TShark and PyShark to inspect captured communication and report descriptive traffic statistics. PCAP Analysis converts captures to SQLite and XML and verifies matching record counts. The automated demonstration records actual socket bytes in a clearly labelled USER0 PCAP. A separate network-capture path supports real IP/TCP captures when an appropriate capture driver is installed.</p>
<h2>Security framework</h2>'''
    synopsis+=table(['Goal','Implemented mechanism','Evidence'],[
        ['Confidentiality','AES-256-GCM with fresh session and direction keys','Encrypted transfers and known-content inspection'],
        ['Integrity','Authenticated headers, chunk offsets and payloads; final file hash','Alteration, missing-chunk and out-of-order tests'],
        ['Authentication','Per-device random secret; transcript-bound HMAC with timestamp','Wrong key, impersonation and expired timestamp rejected'],
        ['Accountability','Device/session/request audit records; independently stored chain checkpoints','Edits, rewritten hashes and truncation detected'],
        ['Availability','Deadlines, limits, backoff, reconnection and persisted offsets','Interrupted upload/download and lost-ACK recovery'],
        ['Replay resistance','Handshake timestamp window, session sequence checks, durable request IDs','Expired-timestamp, encrypted-frame replay and duplicate transaction tests']])
    synopsis+='''<h2>Graphical application</h2><p>A responsive browser frontend provides a transfer workspace, file picker and drag-and-drop, text composer, acknowledged chunk progress, persistent history, verified receiving, image/text previews and playable audio/video. A desktop launcher opens the interface without requiring terminal interaction. One-click local simulation starts the server and audit witness as distinct processes. Security and audit views verify the live authenticated witness checkpoint; traffic analysis decodes actual captures through PyShark and Wireshark/TShark before SQLite/XML conversion. GUI transfers include Ed25519 signed file manifests verified against pinned public keys. Crypto performance displays measured encryption, decryption, hashing, signing and verification times; Testing &amp; results runs and maps the actual isolated security suite.</p><p>The GUI invokes the implemented AES-GCM client/server protocol. Device keys remain in Python rather than being exposed to the frontend. The HTTP user interface binds only to loopback and requires a private application token, with origin and host validation. A remote-device connection option supports the documented two-device lab setup. See the <a href="GUI.md">graphical application guide</a>.</p><h2>Experimental method</h2><p>The demonstration uses separate client, bank and witness processes over loopback as simulated devices. Actual media is uploaded, downloaded, hash-checked and decoded. Controlled tests alter ciphertext and headers, replay encrypted records, submit invalid credentials and oversized requests, interrupt connections and modify audit logs. Tests run with isolated state.</p><p>Efficiency evaluation compares actual secured and plaintext lab transfers with identical chunking and audit policy. Thirty observations per media type and mode follow a discarded warmup, with alternating execution order. Metrics include median and p95 completion latency, useful throughput, process CPU time, sampled resident memory, handshake time and protocol bytes. The separate recovery experiment measures reconnection after a lost completion acknowledgement.</p>
<h2>Threat model and limitations</h2><p>Network attackers and attackers able to modify the bank log are considered. Device secrets, application code, transaction database and independently protected witness state are trusted. Shared-secret compromise does not preserve past confidentiality; forward secrecy and third-party non-repudiation are outside the implemented scope. The witness must run under independent protection for anchored-prefix tamper detection. Loss of the witness intentionally stops accountable completion.</p><p>The same-host experiments do not establish physical isolation, congested-network performance, resistance to arbitrary denial of service or financial-system readiness. The measured CPU and memory values are aggregate process observations. High entropy and absence of known text in a capture support inspection but do not prove cryptographic security. A LAN replication requires the documented two-device setup and capture driver.</p>
<h2>Requirements and deliverables</h2><p>The tested environment is Windows 11 with Python 3.14.3. Dependencies include cryptography, PyShark, psutil, Pillow, FFmpeg via imageio-ffmpeg, Matplotlib and pytest. Linux deployment is supported by the socket-based design but has not been measured in this run. Two networked computers or simulated endpoints are required; three processes provide the client, bank and witness roles.</p><p>Deliverables comprise source code, valid synthetic media, attack tests, a repeatable separate-process demonstration, PCAP captures, SQLite/XML exports, measured benchmark data and charts, a protocol/threat-model specification and this synopsis. See the <a href="EVALUATION.html">evaluation report</a> and <a href="../README.md">setup instructions</a>.</p>'''
    (root/'SYNOPSIS.html').write_text(page('SecureLink Secure Multimedia Communication',synopsis),encoding='utf-8')
    report=f'''<p class="meta">Measured implementation evidence · Windows 11 · Python {html.escape(benchmark['environment']['python'])}</p><p>The regression run contains <strong>{count} tests, {failures} failures or errors and {skipped} skips</strong>. The multimedia demonstration verified text, image, audio and video round trips. The efficiency experiment recorded 240 measured transfers; the supplied summaries report a successful-transfer rate of 100% for every tested mode and media combination.</p><p>These results describe the recorded controlled experiments. They are not universal security or availability guarantees.</p><h2>Requirements and evidence</h2>'''
    report+=table(['Requirement','Implemented evidence'],[
        ['Graphical application','Desktop launcher; responsive transfer, preview, audit and traffic-analysis frontend connected to the real backend'],
        ['At least one approved module','Traffic Analysis plus PCAP-to-SQLite/XML'],
        ['Two devices or simulation','Separate client, bank and witness processes on one Windows host'],
        ['Text, image, audio and video','Valid files transferred both ways; hashes and decoded demo media verified'],
        ['Five security goals','Authentication, AEAD, timestamp anti-replay, anchored auditing and bounded recovery'],
        ['Security analysis','Adversarial tests for replay, tampering, identity, timestamp, audit, framing, quotas and recovery'],
        ['Efficiency analysis','Thirty observations per media/mode with actual acknowledged transfers']])
    report+='<h2>Graphical application</h2><p>The application uses a loopback-only browser frontend with a Python controller. Its local simulation launches distinct server and witness processes and performs the existing encrypted transfers. The graphical workflow supports sending all four media types, verified receiving and browser playback, retained transfer history, resume, independent audit verification and live stream-capture conversion. GUI integration tests cover unauthorized requests, cross-origin/host rejection, file validation, round trips, audit editing, retained transfers after service restart and failed remote authentication. See <a href="GUI.md">the application guide</a>.</p>'
    browser_path=Path('results/gui_browser_summary.json')
    if browser_path.exists():
        browser=json.loads(browser_path.read_text())
        if browser.get('passed'):
            report+='<p>The real-Chrome acceptance run completed '+str(browser['completed_uploads'])+' uploads and '+str(browser['verified_downloads'])+' verified receives, decoded text/image/audio/video previews, checked export downloads and reloads, and confirmed a '+str(browser['responsive_width'])+'-pixel layout without page overflow. Browser script errors: '+str(len(browser['browser_errors']))+'. These checks use isolated state and synthetic media.</p>'
    report+='<h2>Separate process demonstration</h2><p>'+html.escape(process['topology'])+'. Process IDs recorded for this run were client '+str(process['client_pid'])+', bank '+str(process['bank_pid'])+' and witness '+str(process['witness_pid'])+'.</p>'
    report+='<h2>Digital signatures, timing and test requirements</h2><p>The current GUI adds real Ed25519 signatures over a domain-separated file manifest containing its SHA-256, name/media/size, authenticated device and request ID. The receiver pins the signing public key and rejects missing, corrupted, wrong-key or context-modified signatures. Signed manifests persist alongside transfer records. The client verifies the received manifest and complete file before offering previews or downloads. This is distinct from the existing HMAC handshake authentication.</p><p>The Crypto performance page shows actual AES-GCM encryption/decryption, SHA-256 file-read/hash and Ed25519 signing/verification timings in milliseconds, separately for client/server and upload/receive, with counts, processed bytes and failure counts. Client measurements include retries; server measurements cover the final connection up to its last response encoding and exclude that final acknowledgement encryption. Missing operations are explicitly not performed. Hash timing includes disk reads, and instrumentation affects observations. The recorded benchmark_v3 is the earlier unsigned-transfer experiment and is not retroactively relabelled as signature performance.</p><p>The Testing &amp; results page executes the actual isolated pytest suite, displays test durations and pass/fail/skip outcomes, and maps coverage to the ISL requirements. Missing or skipped coverage stays incomplete. The latest real-browser acceptance run exercises these pages and confirms capture decoding through PyShark and Wireshark/TShark without a Python-decoder fallback. See <a href="TESTING.md">the test plan</a>, <a href="../results/gui_crypto_metrics.csv">observed GUI crypto timings</a>, and <a href="../results/gui_test_results.json">GUI test results</a>.</p>'
    report+=table(['File','Bytes','Verified round trip'],[(r['name'],r['bytes'],r['verified']) for r in process['transfers']])
    report+='<h2>Capture analysis</h2><p>The proxy observed actual socket bytes and saved USER0 PCAP records. PyShark/TShark independently read the captures; SQLite and XML conversions matched the record counts. There are no synthetic IP/TCP headers in these files.</p>'
    report+=table(['Mode','Observed records','PyShark records','Known transaction marker visible'],[(mode,demo['modes'][mode]['capture']['records'],demo['modes'][mode].get('pyshark_verified_records','not run'),demo['modes'][mode]['capture']['marker_found']) for mode in ('plaintext','secure')])
    report+='<p>The marker was the literal transaction field <code>"amount_paise"</code>. Its visibility in the baseline and absence in the secured stream are supporting observations. Public metadata, lengths and timing remain visible. Compressed media can have high entropy without encryption. TCP retransmissions and network RTT cannot be measured from these stream records. Npcap was not installed for this run.</p>'
    report+='<h2>Measured efficiency</h2><p>'+html.escape(benchmark['method'])+'</p>'
    report+=table(['Media','Mode','Median ms','p95 ms','Useful MiB/s','CPU ms','Peak RSS MiB'],[(r['file'],r['mode'],f"{r['median_latency_ms']:.2f}",f"{r['p95_latency_ms']:.2f}",f"{r['median_goodput_mib_s']:.4f}",f"{r['median_cpu_ms']:.2f}",f"{r['peak_rss_mib']:.2f}") for r in benchmark['summary']])
    report+='<img src="../results/benchmark_v3/comparison.png" alt="Measured median latency and useful throughput for four media types in secured and plaintext modes"><p>Observed overhead varies with payload size, storage scheduling, audit persistence and shared-host load. A single aggregate overhead percentage would conceal these differences.</p>'
    for limitation in benchmark['limits']:report+='<p>'+html.escape(limitation)+'</p>'
    recovery=demo['recovery']
    report+=f'''<h2>Recovery and duplicate prevention</h2><p>The test closed a connection after a transaction had committed but before the acknowledgement reached the client. The client re-authenticated and retried with the same request ID. The observed recovery took {recovery['recovery_ms']:.2f} ms with {recovery['retries']} reconnection. The ledger contained {recovery['ledger_entries']} transaction entry after a repeated submission. This is one controlled recovery observation; it is not a recovery-time service guarantee.</p><h2>Audit and attack tests</h2><p>Tests reject exact encrypted-record replay, old-session records, expired handshake timestamps, ciphertext/header changes, wrong secrets, wrong server identity, duplicate JSON fields, oversized records, unsafe filenames, incorrect media signatures, mismatched file hashes and invalid chunk offsets. They verify upload/download recovery, durable state reconstruction, owner isolation, connection-limit recovery and service for a legitimate client while another peer stalls.</p><p>Audit tests modify, delete, truncate and recompute local log records, check witness rollback rejection, exercise concurrent writers and simulate witness unavailability. The protected checkpoint assumption is explicit: compromise of both bank and witness is outside the demonstrated guarantee.</p><h2>Reproduction and retained evidence</h2><p><a href="../README.md">Setup and commands</a> · <a href="PROTOCOL.md">Protocol and threat model</a> · <a href="../results/security_tests.xml">Test results</a> · <a href="../results/demo_v3/demo_results.json">Media and recovery results</a> · <a href="../results/two_process_v3/results.json">Separate-process results</a> · <a href="../results/benchmark_v3/measurements.csv">Raw benchmark observations</a></p><p>The original synopsis was retained unchanged. The <a href="SYNOPSIS.html">revised synopsis</a> describes the implemented version and its limits. Physical LAN replication and IP/TCP-level packet capture remain environment-dependent validation steps.</p>'''
    (root/'EVALUATION.html').write_text(page('SecureLink Implementation and Evaluation',report),encoding='utf-8')
    print(f'Built docs/SYNOPSIS.html and docs/EVALUATION.html from {count} test cases')

if __name__=='__main__':build()

